import ast, pathlib
src = pathlib.Path("backend/alembic/versions/0001_initial_schema.py").read_text()
tree = ast.parse(src)
# declared dict
declared = {}
for node in ast.walk(tree):
    if isinstance(node, ast.AnnAssign) and getattr(node.target, "id", "") == "BASELINE_COLUMNS":
        for k, v in zip(node.value.keys, node.value.values):
            cols = set()
            for arg in v.args:
                for elt in arg.elts:
                    cols.add(elt.value)
            declared[k.value] = cols
# create_table calls inside upgrade
created = {}
for node in ast.walk(tree):
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == "create_table":
        name = node.args[0].value
        cols = set()
        for arg in node.args[1:]:
            if isinstance(arg, ast.Call) and arg.func.attr == "Column":
                cols.add(arg.args[0].value)
        created[name] = cols
print("declared keys:", sorted(declared))
print("created  keys:", sorted(created))
ok = True
for t in sorted(set(declared) | set(created)):
    d, c = declared.get(t, set()), created.get(t, set())
    if d != c:
        ok = False
        print(f"MISMATCH {t}: declared-only={sorted(d-c)} created-only={sorted(c-d)}")
    else:
        print(f"match {t}: {len(d)} columns")
print("EXACT MATCH" if ok else "DISAGREEMENT")
